// ─────────────────────────────────────────────
// Combine and deduplicate all word banks
// ─────────────────────────────────────────────
function buildExamWordBank(): StarterWord[] {
  const allWords = [...basic2000Words, ...basic5000Words, ...toeflWords, ...toeicWords];
  const wordMap = new Map<string, StarterWord>();

  for (const entry of allWords) {
    const key = entry.word.toLowerCase();
    if (wordMap.has(key)) {
      const existing = wordMap.get(key)!;
      // Merge exams arrays (deduplicate)
      const mergedExams = Array.from(new Set([...existing.exams, ...entry.exams])) as ExamCategory[];
      wordMap.set(key, { ...existing, exams: mergedExams });
    } else {
      wordMap.set(key, { ...entry });
    }
  }

  // Sort alphabetically
  return Array.from(wordMap.values()).sort((a, b) => a.word.localeCompare(b.word));
}

/** Combined, deduplicated word bank from all exam categories */
export const examWordBank: StarterWord[] = buildExamWordBank();

/** Get the full exam word bank */
export function getExamWordBank(): StarterWord[] {
  return examWordBank;
}

/** Get words for a specific exam category */
export function getWordsByExamCategory(category: ExamCategory): StarterWord[] {
  return examWordBank.filter((w) => w.exams.includes(category));
}

/** Get word count per category */
export function getExamWordCounts(): Record<ExamCategory, number> {
  return {
    '基本2000': getWordsByExamCategory('基本2000').length,
    '基本5000': getWordsByExamCategory('基本5000').length,
    'TOEFL': getWordsByExamCategory('TOEFL').length,
    'TOEIC': getWordsByExamCategory('TOEIC').length,
  };
}
